let activeGame=null,hornUntil=0,materialCache=new Map(),worldLayer=null,emergency=null,incident=null,nextEmergency=0,nextIncident=0,nextParking=0,nextIndoor=0,lastCapture=0;
const cube=new THREE.BoxGeometry(1,1,1),cyl=new THREE.CylinderGeometry(1,1,1,8),sphere=new THREE.SphereGeometry(1,8,6),cone=new THREE.ConeGeometry(1,1,8);
function mat(color,transparent=false,opacity=1){const k=color+','+transparent+','+opacity;if(!materialCache.has(k))materialCache.set(k,new THREE.MeshStandardMaterial({color,roughness:.88,transparent,opacity,depthWrite:!transparent}));return materialCache.get(k);}
function basic(color,opacity=.75){const k='b'+color+opacity;if(!materialCache.has(k))materialCache.set(k,new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:opacity>=1,side:THREE.DoubleSide}));return materialCache.get(k);}
function add(root,geo,material,x,y,z,sx,sy,sz){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.receiveShadow=true;root.add(m);return m;}
function textPlane(text,w=7,h=1.5){const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');x.fillStyle='#172b32';x.fillRect(0,0,c.width,c.height);x.strokeStyle='#d9c79c';x.lineWidth=8;x.strokeRect(5,5,c.width-10,c.height-10);x.fillStyle='#f1e7ca';x.font='800 48px system-ui';x.textAlign='center';x.textBaseline='middle';x.fillText(text,256,66);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:t,transparent:true,side:THREE.DoubleSide,toneMapped:false}));}
function localGround(game,p){return game.terrain.height(p.x,p.z);}

function makeBar(game,h){const root=new THREE.Group(),y=localGround(game,h.p);root.position.set(h.p.x,y,h.p.z);root.userData.phase3Kind='bar';
 add(root,cube,mat('#57453a'),0,1.4,0,5.2,2.8,.55);add(root,cube,mat('#b04d42'),0,2.62,.35,5.4,.18,1.6);
 const sign=textPlane('BAR',2.8,.8);sign.position.set(0,2.05,.31);root.add(sign);
 for(let i=-1;i<=1;i++){add(root,cyl,mat('#5d5145'),i*2,.45,2.0,.42,.08,.42);for(const side of [-1,1])add(root,cube,mat('#76685a'),i*2+side*.7,.42,2.0,.34,.72,.34);for(const side of [-1,1]){add(root,cyl,mat(side<0?'#5f7580':'#9c684f'),i*2+side*.62,1.0,2.15,.18,.62,.18);add(root,sphere,mat('#c69f7f'),i*2+side*.62,1.72,2.15,.16,.18,.16);}}
 root.visible=false;game.scene.add(root);return {...h,root};}
function makeGateway(game,g){const root=new THREE.Group(),y=localGround(game,g.p);root.position.set(g.p.x,y,g.p.z);add(root,cube,mat('#73634f'),-3.6,1.7,0,.22,3.4,.22);add(root,cube,mat('#73634f'),3.6,1.7,0,.22,3.4,.22);const sign=textPlane(g.name,7.4,1.35);sign.position.set(0,2.8,0);root.add(sign);root.visible=false;game.scene.add(root);return {...g,root};}
function makeEvent(game,e){const root=new THREE.Group(),y=game.terrain.height(e.x,e.z);root.position.set(e.x,y,e.z);root.userData.phase3Event=e.type;
 const person=(x,z,color='#6d7d77')=>{add(root,cyl,mat(color),x,.85,z,.17,.65,.17);add(root,sphere,mat('#caa280'),x,1.58,z,.15,.18,.15);};
 if(e.type==='musicista'){person(0,0,'#704d43');add(root,cube,mat('#8d653f'),.45,.85,.12,.36,.62,.12);}
 else if(e.type==='mercatino'){for(let i=-1;i<=1;i++){add(root,cube,mat(i?'#b7644e':'#c89a51'),i*2.4,1.7,0,2.1,.14,1.4);person(i*2.4,.9);}}
 else if(e.type==='studenti'){for(let i=0;i<5;i++)person((i-2)*.7,Math.sin(i)*.45,['#617987','#895c50','#6d7b55'][i%3]);}
 else if(e.type==='cani'){for(let i=0;i<3;i++){person((i-1)*1.4,0);add(root,cube,mat(['#6e523f','#b3946b','#36322f'][i]),(i-1)*1.4+.55,.28,.35,.38,.28,.55);}}
 else if(e.type==='pigeons'){for(let i=0;i<8;i++)add(root,cone,mat('#6b7473'),(i%4-1.5)*.55,.14,Math.floor(i/4)*.65,.12,.22,.12);}
 else if(e.type==='cat'){add(root,cube,mat('#8d765d'),0,.25,0,.5,.28,.25);add(root,sphere,mat('#8d765d'),.32,.38,.08,.22,.22,.22);}
 else if(e.type==='pattini'){for(let i=0;i<3;i++){person((i-1)*1.2,0,'#536c88');add(root,cube,mat('#33393c'),(i-1)*1.2,.06,.2,.55,.06,.16);}}
 else if(e.type==='consegna'){add(root,cube,mat('#aa8b5f'),0,.45,0,1.3,.9,.9);person(1.1,.2,'#526c78');}
 else if(e.type==='lavori'){for(let i=-2;i<=2;i++)add(root,cone,mat('#e68a3b'),i*.75,.36,0,.24,.72,.24);person(0,1.1,'#d9ad43');}
 root.visible=false;game.scene.add(root);return {...e,root};}
function makeBridge(game,b){const root=new THREE.Group(),y=localGround(game,b.p);root.position.set(b.p.x,y+.06,b.p.z);root.userData.phase3Bridge=b.id;
 if(b.kind==='roman-five'){for(let i=-2;i<=2;i++){const x=i*4.15;add(root,cube,mat('#b8a98c'),x,1.0,0,3.6,.45,5.8);const arch=add(root,cyl,mat('#6e746f'),x,-.25,0,1.35,5.9,1.35);arch.rotation.z=Math.PI/2;}for(const side of [-1,1])add(root,cube,mat('#c3b79d'),0,1.75,side*3.0,20.5,.55,.35);}
 else if(b.kind==='istria'){for(const side of [-1,1]){add(root,cube,mat('#d5c7aa'),0,1.0,side*3.4,15,.35,.38);for(let i=-7;i<=7;i+=2)add(root,cube,mat('#e0d4bc'),i,1.55,side*3.4,.28,1.1,.28);}for(let i=0;i<7;i++)add(root,cube,mat('#cfc0a2'),-7+i*2.3,.12+i*.08,7,2.1,.18,1.2);}
 else{for(let i=-1;i<=1;i++)add(root,cube,mat('#b9ac91'),i*3.3,.32,0,3.0,.64,1.1);const plaque=textPlane('PONTE ROMANO · SAN LORENZO',7.5,.95);plaque.position.set(0,1.3,.65);root.add(plaque);}
 root.visible=false;game.scene.add(root);return {...b,root};}
function makeWater(game){const root=new THREE.Group(),waves=[];for(const [i,p] of WATER_POINTS.entries()){const y=game.terrain.waterAt?.(p.x,p.z,0)??game.terrain.height(p.x,p.z);for(let j=0;j<3;j++){const q=new THREE.Mesh(new THREE.PlaneGeometry(9+j*3,.18),basic('#b6e4df',.24));q.rotation.x=-Math.PI/2;q.position.set(p.x+(j-1)*5,y+.08,p.z+(j%2?4:-3));root.add(q);waves.push(q);}if(i<2){const boat=new THREE.Group();add(boat,cube,mat('#694b36'),0,.25,0,1.3,.28,3.8);add(boat,cube,mat('#d2c4a2'),0,.72,-.2,.85,.65,1.4);boat.position.set(p.x+8,y+.05,p.z+6);boat.userData.phase3Boat=true;root.add(boat);}}
 game.scene.add(root);return {root,waves};}
function buildWorldLayer(game){if(worldLayer)return;worldLayer={bars:HOTSPOTS.map(h=>makeBar(game,h)),gateways:GATEWAYS.map(g=>makeGateway(game,g)),events:EVENTS.map(e=>makeEvent(game,e)),bridges:BRIDGES.map(b=>makeBridge(game,b)),water:makeWater(game)};}
function updateWorldLayer(game){if(!worldLayer)return;const s=game.state,hyper=s.quality==='hyper',range=hyper?340:s.quality==='low'?520:760;
 for(const b of worldLayer.bars)b.root.visible=!hyper&&dist(s,b.p)<range;
 for(const g of worldLayer.gateways)g.root.visible=dist(s,g.p)<range;
 for(const e of worldLayer.events)e.root.visible=!hyper&&Math.hypot(s.x-e.x,s.z-e.z)<range*.82;
 for(const b of worldLayer.bridges)b.root.visible=dist(s,b.p)<range;
 worldLayer.water.root.visible=!hyper;for(const [i,w] of worldLayer.water.waves.entries()){w.visible=s.quality!=='hyper'&&(s.quality!=='low'||i%3===0);w.material.opacity=.18+.08*Math.sin(s.elapsed*1.2+i);w.position.y+=Math.sin(s.elapsed*1.6+i)*.0008;}
 for(const o of worldLayer.water.root.children)if(o.userData.phase3Boat){o.visible=['medium','high'].includes(s.quality);if(o.visible){o.position.x+=Math.sin(s.elapsed*.16+o.id)*.004;o.rotation.y=Math.sin(s.elapsed*.11+o.id)*.08;}}
}

function installIntro(){
 if(document.getElementById('phase3IntroStyle'))return;const style=document.createElement('style');style.id='phase3IntroStyle';style.textContent=`.intro{overflow:hidden}.phase3-intro-backdrop{position:absolute;inset:-5%;z-index:-2;filter:blur(10px) brightness(.42);transform:scale(1.08);overflow:hidden}.phase3-intro-backdrop span{position:absolute;inset:0;background-size:cover;background-position:center;opacity:0;animation:phase3shot 24s infinite;transform:scale(1.06)}.phase3-intro-backdrop span:nth-child(2){animation-delay:8s}.phase3-intro-backdrop span:nth-child(3){animation-delay:16s}@keyframes phase3shot{0%,100%{opacity:0;transform:translateX(2%) scale(1.08)}8%,28%{opacity:1}36%{opacity:0;transform:translateX(-2%) scale(1.12)}}#tourBtn{margin-left:.55rem}.tour-badge{position:fixed;left:50%;top:74px;transform:translateX(-50%);z-index:35;background:rgba(11,28,34,.86);border:1px solid rgba(255,255,255,.16);padding:7px 13px;border-radius:999px;font:700 12px system-ui;color:#f4e8c7;letter-spacing:.08em}`;document.head.appendChild(style);
 const intro=document.getElementById('intro'),play=document.getElementById('playBtn');if(intro&&play&&!document.getElementById('tourBtn')){const b=document.createElement('button');b.id='tourBtn';b.className='textbutton';b.textContent='VISITA CITTÀ';b.onclick=()=>{sessionStorage.setItem(TOUR_KEY,'1');play.click();};play.after(b);}
 let shots=[];try{shots=JSON.parse(localStorage.getItem(SHOT_KEY)||'[]');}catch{}if(intro&&shots.length){const bg=document.createElement('div');bg.className='phase3-intro-backdrop';for(const src of shots.slice(-3)){const s=document.createElement('span');s.style.backgroundImage=`url(${src})`;bg.appendChild(s);}intro.prepend(bg);}
}
function captureShot(game){if(game.state.elapsed-lastCapture<35||document.getElementById('playingUI')?.hidden)return;lastCapture=game.state.elapsed;const source=document.getElementById('world');if(!source?.width)return;try{const c=document.createElement('canvas');c.width=640;c.height=360;c.getContext('2d').drawImage(source,0,0,c.width,c.height);const url=c.toDataURL('image/webp',.42);let shots=[];try{shots=JSON.parse(localStorage.getItem(SHOT_KEY)||'[]');}catch{}shots.push(url);while(shots.length>3)shots.shift();localStorage.setItem(SHOT_KEY,JSON.stringify(shots));}catch{}}
function tourOn(){return sessionStorage.getItem(TOUR_KEY)==='1';}
function updateTour(game){if(!tourOn())return;const s=game.state;s.wanted=0;s.escape=0;s.busted=0;if(s.mission){s.mission=null;s.route=[];}game.wantedLevel=0;game.graceUntil=s.elapsed+999;game.clearEnemies?.();game.clearRoadblocks?.();while(game.cops.length){const c=game.cops.at(-1);game.remove(c);}const btn=document.getElementById('activityBtn');if(btn){btn.disabled=true;btn.textContent='VISITA CITTÀ · NESSUNA MISSIONE';}if(!document.getElementById('tourBadge')){const d=document.createElement('div');d.id='tourBadge';d.className='tour-badge';d.textContent='VISITA CITTÀ · FREE EXPLORE';document.body.appendChild(d);}}

let audioCtx=null;function horn(game){hornUntil=game.state.elapsed+1.6;if(game.state.sound){try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const now=audioCtx.currentTime,g=audioCtx.createGain();g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.07,now+.015);g.gain.exponentialRampToValueAtTime(.0001,now+.24);g.connect(audioCtx.destination);for(const hz of [392,466]){const o=audioCtx.createOscillator();o.type='square';o.frequency.value=hz;o.connect(g);o.start(now);o.stop(now+.25);}}catch{}}game.toast('CLACSON',.8);}
document.addEventListener('keydown',e=>{if(e.code!=='KeyH'||e.repeat||!activeGame||document.querySelector('dialog[open]'))return;const s=activeGame.state;if(s.mode!=='car'||s.car?.spec.aircraft)return;e.preventDefault();horn(activeGame);});

function reactPeople(game){const s=game.state,source=hornUntil>s.elapsed?s:emergency?.car;if(!source)return;for(const p of game.people){if(!p.mesh?.visible||dist(p,source)>34)continue;p.phase3ReactionUntil=Math.max(p.phase3ReactionUntil||0,s.elapsed+2.2);const dx=p.x-source.x,dz=p.z-source.z,l=Math.hypot(dx,dz)||1,nx=p.x+dx/l*.16,nz=p.z+dz/l*.16;if(game.terrain.dry(nx,nz,.25)){const blocked=[...game.collision.near(nx,nz,.3)].some(b=>b.p&&pointInside(nx,nz,b.p));if(!blocked){p.x=nx;p.z=nz;p.yaw=Math.atan2(dx,dz);}}}}
function indoorPeople(game){const now=game.state.elapsed;if(now>=nextIndoor){nextIndoor=now+5.5;const choices=game.people.filter(p=>p.mesh?.visible&&!p.dog&&dist(p,game.state)>35&&dist(p,game.state)<260&&!p.phase3IndoorUntil);const p=choices[Math.floor(Math.random()*choices.length)];if(p){const buildings=[...game.collision.near(p.x,p.z,18)].filter(b=>b.p&&b.h&&!b.kind);const b=buildings[0];if(b){p.phase3IndoorUntil=now+7+Math.random()*8;p.phase3IndoorExit=now+3;p.phase3IndoorBuilding=b;}}}
 for(const p of game.people){if(!p.phase3IndoorUntil)continue;if(now>=p.phase3IndoorUntil){p.mesh.visible=true;p.phase3IndoorUntil=0;p.phase3IndoorBuilding=null;continue;}if(now>=p.phase3IndoorExit){p.mesh.visible=false;continue;}const b=p.phase3IndoorBuilding;if(b){const cx=b.cx??b.p.reduce((a,q)=>a+q[0],0)/b.p.length,cz=b.cz??b.p.reduce((a,q)=>a+q[1],0)/b.p.length,dx=cx-p.x,dz=cz-p.z,l=Math.hypot(dx,dz)||1;p.x+=dx/l*.08;p.z+=dz/l*.08;p.yaw=Math.atan2(dx,dz);}}
}

function parkingSpot(game){const candidates=[];for(const seg of game.graph.index.near(game.state.x,game.state.z,380)){const r=seg.road;if(!seg.connected||r.w<6||r.w>15||!['residential','tertiary','secondary','unclassified','service'].includes(r.k)||['no','private'].includes(r.access))continue;const a=game.graph.nodes[seg.a],b=game.graph.nodes[seg.b],t=.25+Math.random()*.5,x=a.x+(b.x-a.x)*t,z=a.z+(b.z-a.z)*t,d=dist({x,z},game.state);if(d<90||d>350)continue;const yaw=Math.atan2(b.x-a.x,b.z-a.z),side=Math.random()<.5?-1:1,off=Math.max(2.2,r.w/2-1.0),px=x+Math.cos(yaw)*side*off,pz=z-Math.sin(yaw)*side*off,y=game.terrain.height(px,pz),spec=VEHICLES.compact;if(!game.terrain.dry(px,pz,spec.width/2,y)||vehicleBlocked(px,pz,yaw,game.collision,spec,y)||game.cars.some(c=>c.mesh.visible&&dist(c,{x:px,z:pz})<7))continue;candidates.push({x:px,z:pz,y,yaw});}return candidates[Math.floor(Math.random()*candidates.length)]||null;}
function updateParking(game){const now=game.state.elapsed,limit=game.state.quality==='hyper'?0:game.state.quality==='low'?4:game.state.quality==='medium'?7:10;game.phase3Parked??=[];for(const c of [...game.phase3Parked])if(c!==game.state.car&&(!c.mesh.visible||dist(c,game.state)>760)){game.retire(c);game.phase3Parked.splice(game.phase3Parked.indexOf(c),1);}if(now<nextParking||game.phase3Parked.length>=limit)return;nextParking=now+7;const p=parkingSpot(game);if(!p)return;const style=Math.random()<.65?'compact':'wagon',c=game.addCar(p.x,p.z,p.yaw,false,true,style);Object.assign(c,{y:p.y,speed:0,parked:true,phase3Parked:true,name:'Auto parcheggiata'});game.pose(c);game.phase3Parked.push(c);}

function randomGoal(game,from,min=280,max=750){const nodes=[];for(const seg of game.graph.index.near(from.x,from.z,max)){if(!seg.connected||seg.road.w<5||['no','private'].includes(seg.road.access)||seg.road.k==='pedestrian')continue;for(const id of [seg.a,seg.b]){const n=game.graph.nodes[id],d=dist(n,from);if(d>min&&d<max)nodes.push(n);}}return nodes[Math.floor(Math.random()*nodes.length)]||null;}
function decorateEmergency(c,kind){const root=new THREE.Group();root.name='phase3-emergency-kit';const color=kind==='fire'?'#c54034':'#f2f0e8',stripe=kind==='fire'?'#f1d35f':'#d6413b';add(root,cube,mat(color),0,c.spec.height*.52,0,c.spec.width*.92,c.spec.height*.74,c.spec.length*.7);add(root,cube,mat(stripe),0,c.spec.height*.55,c.spec.length*.12,c.spec.width*.95,.18,c.spec.length*.62);for(const side of [-1,1]){const l=add(root,cube,basic(side<0?'#398cff':'#ff4d48'),side*.32,c.spec.height+.12,-.1,.28,.12,.22);(c.phase3Lights??=[]).push(l);}c.mesh.add(root);c.name=kind==='fire'?'Vigili del Fuoco':'Ambulanza';c.missionUnit=true;c.phase3Emergency=kind;}
function spawnEmergency(game,goal=null){if(emergency)return;const kind=Math.random()<.38?'fire':'ambulance',style=kind==='fire'?'truck':'utility',p=game.findSpawn(style,150,390);if(!p)return;goal??=randomGoal(game,p);if(!goal)return;const path=roadRoute(p,goal,game.graph);if(path.length<3)return;const c=game.addCar(p.x,p.z,p.yaw,false,false,style);decorateEmergency(c,kind);Object.assign(c,{y:p.y,speed:12,path,pathIndex:1,stuck:0,phase3Expires:game.state.elapsed+42});game.pose(c);emergency={car:c,goal,path};}
function updateEmergency(game,dt){nextEmergency||=game.state.elapsed+55+Math.random()*50;if(!emergency){if(game.state.elapsed>=nextEmergency&&game.state.wanted===0&&!game.state.mission){spawnEmergency(game);nextEmergency=game.state.elapsed+110+Math.random()*100;}return;}const c=emergency.car;if(c===game.state.car){emergency=null;return;}if(game.state.elapsed>c.phase3Expires||dist(c,game.state)>900||!c.mesh.visible){game.retire(c);emergency=null;return;}if(c.pathIndex>=c.path.length-1){c.speed=0;c.phase3Expires=Math.min(c.phase3Expires,game.state.elapsed+7);}else followRoad(c,dt,game.graph,game.terrain,game.collision,{max:c.phase3Emergency==='fire'?23:28,accel:10,turnRate:1.6,traffic:game.cars.filter(a=>a!==c)});if(c.phase3Lights)for(const [i,l] of c.phase3Lights.entries())l.visible=Math.sin(game.state.elapsed*14+i*Math.PI)>0;game.pose(c);}
function spawnIncident(game){if(incident||game.state.wanted||game.state.mission)return;const p=game.findSpawn('compact',170,390);if(!p)return;const car=game.addCar(p.x,p.z,p.yaw,false,true,Math.random()<.5?'compact':'sedan');Object.assign(car,{y:p.y,speed:0,parked:true,missionUnit:true,phase3Incident:true,name:'Veicolo incidentato'});car.health=35;game.pose(car);const root=new THREE.Group();for(const side of [-1,1])for(let i=0;i<3;i++){const c=add(root,cone,mat('#e78437'),p.x+Math.cos(p.yaw)*side*1.5-Math.sin(p.yaw)*(3+i*1.4),p.y+.36,p.z-Math.sin(p.yaw)*side*1.5-Math.cos(p.yaw)*(3+i*1.4),.24,.72,.24);c.rotation.y=p.yaw;}game.scene.add(root);incident={car,root,expires:game.state.elapsed+34};setTimeout(()=>{if(activeGame&&incident?.car===car)spawnEmergency(activeGame,{x:car.x,z:car.z});},1800);}
function updateIncident(game){nextIncident||=game.state.elapsed+70+Math.random()*55;if(!incident){if(game.state.elapsed>=nextIncident){spawnIncident(game);nextIncident=game.state.elapsed+125+Math.random()*100;}return;}if(game.state.elapsed>incident.expires||incident.car===game.state.car||dist(incident.car,game.state)>850){if(incident.car!==game.state.car)game.retire(incident.car);game.scene.remove(incident.root);incident=null;}}
function trafficBypass(game,dt){for(const c of game.cars){if(c===game.state.car||c.parked||c.police||c.spec?.aircraft||c.speed>5||!c.mesh.visible)continue;let block=null,best=12;for(const o of game.cars){if(o===c||!o.mesh.visible||Math.abs((o.y||0)-(c.y||0))>3||Math.abs(o.speed)>1.5)continue;const dx=o.x-c.x,dz=o.z-c.z,ahead=dx*Math.sin(c.yaw)+dz*Math.cos(c.yaw),side=Math.abs(dx*Math.cos(c.yaw)-dz*Math.sin(c.yaw));if(ahead>2&&ahead<best&&side<(c.spec.width+o.spec.width)/2+.7){block=o;best=ahead;}}if(!block)continue;c.phase3AvoidSide??=((c.mesh.id%2)?1:-1);const side=c.phase3AvoidSide,step=Math.min(.55,dt*2.2),nx=c.x+Math.cos(c.yaw)*side*step,nz=c.z-Math.sin(c.yaw)*side*step,y=game.terrain.height(nx,nz,c.y);if(game.terrain.dry(nx,nz,c.spec.width/2,y)&&!vehicleBlocked(nx,nz,c.yaw,game.collision,c.spec,y)){c.x=nx;c.z=nz;c.y=y;c.speed=Math.max(c.speed,3.2);game.pose(c);}}
}

const baseSignalPhase=TrafficSignals.prototype.phase,baseSignalUpdate=TrafficSignals.prototype.update;
TrafficSignals.prototype.phase=function(id,time,heading){const j=this.junctions.get(id);if(!j||j.phase3Priority==null)return baseSignalPhase.call(this,id,time,heading);const axis=Math.abs(Math.sin(heading))>.707?1:0,p=(time+j.offset)%30;if(j.phase3Priority===0){if(p<15)return axis===0?'green':'red';if(p<17)return axis===0?'amber':'red';if(p<18)return'red';if(p<27)return axis===1?'green':'red';if(p<29)return axis===1?'amber':'red';return'red';}if(p<9)return axis===0?'green':'red';if(p<11)return axis===0?'amber':'red';if(p<12)return'red';if(p<27)return axis===1?'green':'red';if(p<29)return axis===1?'amber':'red';return'red';};
TrafficSignals.prototype.update=function(scene,terrain,x,z,time){if(time>(this.phase3DemandAt||0)){this.phase3DemandAt=time+.8;const actors=activeGame?[...activeGame.cars,...activeGame.cops]:[];for(const j of this.junctions.values()){let a0=0,a1=0;for(const c of actors){if(!c.mesh?.visible||c.parked||dist(c,j)>55)continue;const axis=Math.abs(Math.sin(c.yaw))>.707?1:0,w=Math.abs(c.speed)<6?1.4:1;if(axis)a1+=w;else a0+=w;}j.phase3Priority=a0>a1+2?0:a1>a0+2?1:null;}}return baseSignalUpdate.call(this,scene,terrain,x,z,time);};

const baseTramUpdate=Trams.prototype.update;
Trams.prototype.update=function(dt,time,player,actors,kick){const out=baseTramUpdate.call(this,dt,time,player,actors,kick);if(!this.phase3Passengers){const body=new THREE.InstancedMesh(cyl,mat('#607786'),24),head=new THREE.InstancedMesh(sphere,mat('#c59a79'),24);this.scene.add(body,head);this.phase3Passengers={body,head,dummy:new THREE.Object3D()};}const {body,head,dummy}=this.phase3Passengers;let count=0;for(const route of this.routes.slice(0,1))for(const stop of route.stops||[]){const pose=sampleRail(route,stop);if(dist(pose,player)>520)continue;const dwelling=this.vehicles.some(t=>t.route===route&&t.dwell>0&&Math.abs(t.d-stop)<3),num=dwelling?2:4;for(let i=0;i<num&&count<24;i++){const side=i%2?-1:1,x=pose.x+Math.cos(pose.yaw)*side*(2.1+Math.floor(i/2)*.75),z=pose.z-Math.sin(pose.yaw)*side*(2.1+Math.floor(i/2)*.75),walk=dwelling?clamp(1-t.dwell/4,0,1):0,tx=x+(pose.x-x)*walk,tz=z+(pose.z-z)*walk,y=this.terrain.height(tx,tz);dummy.position.set(tx,y+.72,tz);dummy.scale.set(.18,.72,.18);dummy.updateMatrix();body.setMatrixAt(count,dummy.matrix);dummy.position.y=y+1.55;dummy.scale.set(.15,.18,.15);dummy.updateMatrix();head.setMatrixAt(count,dummy.matrix);count++;}}body.count=head.count=count;body.instanceMatrix.needsUpdate=head.instanceMatrix.needsUpdate=true;return out;};

const baseGameplayUpdate=ModernGameplay.prototype.update;
if(!ModernGameplay.prototype.__phase3CitySystems){ModernGameplay.prototype.__phase3CitySystems=true;ModernGameplay.prototype.update=function(dt){baseGameplayUpdate.call(this,dt);activeGame=this;buildWorldLayer(this);updateTour(this);updateWorldLayer(this);updateParking(this);indoorPeople(this);updateIncident(this);updateEmergency(this,dt);trafficBypass(this,dt);reactPeople(this);captureShot(this);};}
